actor OrderProcess {
    private var state: OrderState = .awaitingPayment

    func handle(_ ev: OrderEvent) async throws {
        switch (state, ev) {
        case (.awaitingPayment, .paymentOk):
            state = .awaitingStock                 // update before any await
            try await outbox.enqueue(.reserveStock(id))
        case (.awaitingPayment, .timeout):
            state = .compensating
            try await outbox.enqueue(.releaseCredit(id))
        default:
            break                                  // duplicate or stale reply
        }
    }
}
